web/style.css.content:
:root {
  --bg: #020503;
  --panel: rgba(4, 14, 8, .82);
  --panel-strong: rgba(3, 9, 5, .94);
  --green: #52ff87;
  --green-2: #18d957;
  --green-soft: #8affac;
  --green-dim: #26723d;
  --text: #d8ffe2;
  --muted: #72a880;
  --line: rgba(82, 255, 135, .26);
  --danger: #ff5c70;
  --warning: #ffd166;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  width: 100%;
  height: 100%;
  background: var(--bg);
  color: var(--text);
  font-family: Consolas, "Cascadia Mono", "Courier New", monospace;
  overflow: hidden;
}

body {
  height: 100vh;
}

#matrix {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100%;
  z-index: 0;
  opacity: .24;
}

.noise,
.scanline {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 1;
}

.noise {
  opacity: .035;
  background-image:
    repeating-linear-gradient(0deg, #fff 0 1px, transparent 1px 3px),
    repeating-linear-gradient(90deg, #fff 0 1px, transparent 1px 5px);
  mix-blend-mode: screen;
}

.scanline::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  height: 120px;
  background: linear-gradient(transparent, rgba(80,255,130,.045), transparent);
  animation: scan 7s linear infinite;
}

@keyframes scan {
  from { transform: translateY(-140px); }
  to { transform: translateY(110vh); }
}

.side-handle {
  position: fixed;
  top: 50%;
  z-index: 12;
  width: 34px;
  height: 132px;
  transform: translateY(-50%);
  border: 1px solid rgba(82,255,135,.24);
  background: rgba(3,18,8,.82);
  color: var(--green-soft);
  box-shadow: 0 0 22px rgba(18,255,91,.05);
  cursor: pointer;
  font: 700 9px/1 Consolas, "Cascadia Mono", monospace;
  letter-spacing: .12em;
  transition: background .18s ease, border-color .18s ease, color .18s ease;
}

.side-handle:hover,
.side-handle:focus-visible {
  background: rgba(6,34,14,.96);
  border-color: rgba(82,255,135,.62);
  color: var(--green);
  outline: none;
}

.side-handle span {
  display: inline-block;
  writing-mode: vertical-rl;
  transform: rotate(180deg);
}

.side-handle-left {
  left: 0;
  border-left: 0;
}

.side-handle-right {
  right: 0;
  border-right: 0;
}

.side-panel {
  position: fixed;
  top: 18px;
  bottom: 18px;
  z-index: 30;
  width: min(360px, calc(100vw - 70px));
  display: flex;
  flex-direction: column;
  border: 1px solid rgba(82,255,135,.30);
  background:
    linear-gradient(180deg, rgba(3,17,8,.985), rgba(2,8,4,.985));
  box-shadow: 0 0 46px rgba(0,0,0,.58), inset 0 0 40px rgba(82,255,135,.025);
  transition: transform .22s ease;
}

.side-panel-left {
  left: 0;
  border-left: 3px solid var(--green);
  transform: translateX(calc(-100% - 8px));
}

.side-panel-right {
  right: 0;
  border-right: 3px solid var(--green);
  transform: translateX(calc(100% + 8px));
}

.side-panel.open {
  transform: translateX(0);
}

.side-panel-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  padding: 18px 18px 14px;
  border-bottom: 1px solid var(--line);
}

.side-panel-head h2 {
  margin-top: 5px;
  color: #e7ffed;
  font-size: 19px;
  letter-spacing: .04em;
}

.side-panel-close {
  width: 30px;
  height: 30px;
  display: grid;
  place-items: center;
  border: 1px solid rgba(82,255,135,.26);
  background: rgba(10,55,23,.18);
  color: var(--green);
  cursor: pointer;
  font: 400 21px/1 Consolas, monospace;
}

.side-panel-close:hover,
.side-panel-close:focus-visible {
  background: var(--green);
  color: #001905;
  outline: none;
}

.side-panel-body {
  flex: 1 1 auto;
  min-height: 0;
  overflow-y: auto;
  overflow-x: hidden;
  padding: 16px;
  scrollbar-width: thin;
  scrollbar-color: rgba(82,255,135,.42) rgba(2,9,4,.60);
}

.side-panel-body::-webkit-scrollbar {
  width: 8px;
}

.side-panel-body::-webkit-scrollbar-track {
  background: rgba(2,9,4,.60);
}

.side-panel-body::-webkit-scrollbar-thumb {
  background: rgba(82,255,135,.42);
  border: 2px solid rgba(2,9,4,.60);
}

.side-placeholder {
  padding: 18px;
  border: 1px dashed rgba(82,255,135,.22);
  background: rgba(2,10,5,.72);
}

.side-placeholder strong {
  color: var(--green-soft);
  font-size: 12px;
  letter-spacing: .10em;
}

.side-placeholder p {
  margin-top: 9px;
  color: #7ca287;
  font: 12px/1.55 "Segoe UI", Arial, sans-serif;
}

.side-panel-backdrop {
  position: fixed;
  inset: 0;
  z-index: 25;
  background: rgba(0,0,0,.24);
  opacity: 0;
  pointer-events: none;
  transition: opacity .18s ease;
}

.side-panel-backdrop.show {
  opacity: 1;
  pointer-events: auto;
}

.shell {
  position: relative;
  z-index: 2;
  width: min(1480px, calc(100% - 48px));
  height: 100vh;
  margin: 0 auto;
  padding: 14px 0 12px;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  padding: 12px 18px;
  border: 1px solid var(--line);
  border-left: 3px solid var(--green);
  background: linear-gradient(90deg, rgba(3,18,8,.96), rgba(3,10,6,.72));
  box-shadow: 0 0 34px rgba(18,255,91,.07);
}

.brand {
  display: flex;
  align-items: center;
  gap: 14px;
}

.brand-mark {
  color: #001905;
  background: var(--green);
  font-size: 20px;
  font-weight: 900;
  padding: 8px 10px;
  box-shadow: 0 0 20px rgba(82,255,135,.25);
  flex: 0 0 auto;
}

.company-name {
  margin-top: 3px !important;
  color: var(--green-soft) !important;
  font-size: 10px !important;
  letter-spacing: .12em !important;
  text-transform: uppercase;
}

h1, h2, h3, h4, p { margin: 0; }

h1 {
  color: var(--green);
  font-size: 17px;
  letter-spacing: .18em;
}

.brand p {
  margin-top: 4px;
  color: var(--muted);
  font-size: 11px;
  letter-spacing: .1em;
}

.node-state {
  display: flex;
  align-items: center;
  gap: 9px;
  color: var(--green-soft);
  font-size: 12px;
  white-space: nowrap;
}

.pulse {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--green);
  box-shadow: 0 0 12px var(--green);
  animation: blink 1.4s ease-in-out infinite;
}

@keyframes blink {
  50% { opacity: .28; transform: scale(.78); }
}

.divider { color: var(--green-dim); }

.hero {
  display: grid;
  grid-template-columns: 1.18fr .82fr;
  gap: 22px;
  align-items: stretch;
  padding: 26px 0 20px;
  flex: 0 0 auto;
}

.eyebrow {
  color: var(--green-2);
  letter-spacing: .16em;
  font-size: 11px;
  font-weight: 700;
}

.hero h2 {
  margin-top: 12px;
  font-size: clamp(36px, 5vw, 72px);
  line-height: .98;
  letter-spacing: -.055em;
  max-width: 800px;
}

.hero h2 span {
  color: var(--green);
  text-shadow: 0 0 22px rgba(82,255,135,.18);
}

.hero-copy {
  margin-top: 14px;
  max-width: 740px;
  color: #93b69c;
  font-family: "Segoe UI", Arial, sans-serif;
  line-height: 1.65;
  font-size: 15px;
}

.terminal-card {
  border: 1px solid var(--line);
  background: var(--panel-strong);
  height: 205px;
  min-height: 205px;
  max-height: 205px;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  box-shadow: inset 0 0 55px rgba(18,255,91,.035), 0 24px 70px rgba(0,0,0,.28);
}

.terminal-head {
  height: 36px;
  flex: 0 0 36px;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 0 14px;
  border-bottom: 1px solid var(--line);
  color: var(--muted);
  font-size: 11px;
}

.terminal-head span {
  width: 8px;
  height: 8px;
  border: 1px solid var(--green-dim);
  border-radius: 50%;
}

.terminal-head strong {
  margin-left: 6px;
  font-weight: 400;
}

.terminal-body {
  flex: 1 1 auto;
  min-height: 0;
  padding: 14px 16px;
  overflow-y: auto;
  overflow-x: hidden;
  overscroll-behavior: contain;
  scrollbar-width: thin;
  scrollbar-color: rgba(82,255,135,.48) rgba(1,8,3,.72);
  color: #91c69f;
  font-size: 12px;
  line-height: 1.55;
}

.terminal-body::-webkit-scrollbar {
  width: 9px;
}

.terminal-body::-webkit-scrollbar-track {
  background: rgba(1,8,3,.72);
}

.terminal-body::-webkit-scrollbar-thumb {
  background: rgba(82,255,135,.48);
  border: 2px solid rgba(1,8,3,.72);
}

.terminal-body::-webkit-scrollbar-thumb:hover {
  background: rgba(82,255,135,.72);
}

.terminal-body p {
  margin: 0 0 2px;
}

.terminal-body b { color: var(--green); }
.terminal-body .ok { color: var(--green); }
.terminal-body .muted { color: var(--muted); }

.process-library {
  width: 100%;
  margin: 0 0 14px;
  flex: 0 0 auto;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 12px;
}

.process-library-card {
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 12px;
  min-height: 70px;
  padding: 10px 12px;
  border: 1px solid rgba(82,255,135,.28);
  border-left: 3px solid var(--green);
  background: linear-gradient(90deg, rgba(3,18,8,.92), rgba(2,10,5,.78));
  color: inherit;
  text-decoration: none;
  box-shadow:
    inset 0 0 36px rgba(82,255,135,.025),
    0 14px 36px rgba(0,0,0,.18);
  transition:
    border-color .18s ease,
    transform .18s ease,
    box-shadow .18s ease,
    background .18s ease;
}

.process-library-card:hover {
  transform: translateY(-1px);
  border-color: rgba(82,255,135,.56);
  background: linear-gradient(90deg, rgba(4,24,10,.96), rgba(2,12,6,.84));
  box-shadow:
    inset 0 0 42px rgba(82,255,135,.04),
    0 16px 42px rgba(0,0,0,.24),
    0 0 18px rgba(82,255,135,.05);
}

.process-library-icon {
  width: 46px;
  height: 46px;
  display: grid;
  place-items: center;
  color: #001905;
  background: var(--green);
  border: 1px solid rgba(82,255,135,.72);
  box-shadow: 0 0 18px rgba(82,255,135,.16);
  font: 900 22px/1 Consolas, "Cascadia Mono", monospace;
}

.process-library-copy {
  min-width: 0;
}

.process-library-copy h3 {
  margin-top: 4px;
  color: #e7ffed;
  font-size: 16px;
  letter-spacing: .03em;
}

.process-library-copy > p:last-child {
  margin-top: 4px;
  color: #86aa90;
  font: 11px/1.35 "Segoe UI", Arial, sans-serif;
}

.process-library-action {
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--green);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: .10em;
  white-space: nowrap;
}

.process-library-action strong {
  font-size: 20px;
  font-weight: 400;
  transition: transform .18s ease;
}

.process-library-card:hover .process-library-action strong {
  transform: translateX(4px);
}

.process-library-card.resource-disabled {
  opacity: .56;
  cursor: default;
  border-color: rgba(82,255,135,.16);
}

.process-library-card.resource-disabled:hover {
  transform: none;
  border-color: rgba(82,255,135,.16);
  background: linear-gradient(90deg, rgba(3,18,8,.92), rgba(2,10,5,.78));
  box-shadow:
    inset 0 0 36px rgba(82,255,135,.025),
    0 14px 36px rgba(0,0,0,.18);
}

.process-library-card.resource-disabled .process-library-icon {
  background: rgba(82,255,135,.52);
}

.process-tree {
  display: flex;
  flex-direction: column;
  gap: 7px;
}

.process-node {
  border: 1px solid rgba(82,255,135,.12);
  background: rgba(2,10,5,.56);
}

.process-node + .process-node {
  margin-top: 2px;
}

.process-toggle,
.process-document {
  width: 100%;
  display: grid;
  grid-template-columns: 18px 1fr auto;
  align-items: center;
  gap: 8px;
  border: 0;
  background: transparent;
  color: #bceac7;
  text-align: left;
  cursor: pointer;
  font-family: Consolas, "Cascadia Mono", monospace;
}

.process-toggle {
  padding: 10px 10px;
}

.process-toggle:hover,
.process-toggle:focus-visible,
.process-document:hover,
.process-document:focus-visible {
  background: rgba(82,255,135,.07);
  color: var(--green);
  outline: none;
}

.process-toggle[aria-disabled="true"] {
  cursor: default;
  color: #617c68;
}

.process-toggle[aria-disabled="true"]:hover {
  background: transparent;
}

.process-chevron {
  color: var(--green-dim);
  font-size: 12px;
  transition: transform .16s ease;
}

.process-toggle[aria-expanded="true"] .process-chevron {
  transform: rotate(90deg);
  color: var(--green);
}

.process-label {
  min-width: 0;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: .035em;
}

.process-count {
  color: var(--muted);
  font-size: 9px;
  font-weight: 400;
}

.process-children {
  display: none;
  padding: 0 0 7px 12px;
  margin-left: 9px;
  border-left: 1px solid rgba(82,255,135,.16);
}

.process-node.open > .process-children {
  display: block;
}

.process-children .process-node {
  border-color: transparent;
  background: transparent;
}

.process-children .process-toggle {
  padding: 8px 8px;
}

.process-document {
  padding: 8px 8px;
  color: #90be9b;
}

.process-document .process-doc-icon {
  color: var(--green);
  font-size: 10px;
}

.process-empty {
  padding: 8px 10px 9px 28px;
  color: #536d59;
  font: 10px/1.4 "Segoe UI", Arial, sans-serif;
}

.pdf-modal {
  position: fixed;
  inset: 0;
  z-index: 60;
  display: none;
}

.pdf-modal.open {
  display: block;
}

.pdf-modal-backdrop {
  position: absolute;
  inset: 0;
  background: rgba(0,0,0,.72);
  backdrop-filter: blur(2px);
}

.pdf-modal-window {
  position: absolute;
  inset: 4vh 4vw;
  display: flex;
  flex-direction: column;
  border: 1px solid rgba(82,255,135,.42);
  border-left: 3px solid var(--green);
  background: #020503;
  box-shadow: 0 0 70px rgba(0,0,0,.72), 0 0 28px rgba(82,255,135,.07);
}

.pdf-modal-head {
  min-height: 70px;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 18px;
  padding: 14px 16px;
  border-bottom: 1px solid var(--line);
  background: linear-gradient(90deg, rgba(3,18,8,.98), rgba(2,9,5,.94));
}

.pdf-modal-head h2 {
  margin-top: 4px;
  color: #e7ffed;
  font-size: 18px;
}

.pdf-modal-head > div > p:last-child {
  margin-top: 4px;
  color: var(--muted);
  font-size: 10px;
}

.pdf-modal-close {
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  border: 1px solid rgba(82,255,135,.3);
  background: rgba(12,72,30,.16);
  color: var(--green);
  cursor: pointer;
  font: 400 22px/1 Consolas, monospace;
}

.pdf-modal-close:hover,
.pdf-modal-close:focus-visible {
  background: var(--green);
  color: #001905;
  outline: none;
}

.pdf-modal-body {
  flex: 1 1 auto;
  min-height: 0;
  background: #0a0a0a;
}

.pdf-modal-body {
  position: relative;
  overflow: auto;
  padding: 18px;
  background:
    linear-gradient(180deg, rgba(5,10,7,.98), rgba(1,4,2,.99));
  scrollbar-width: thin;
  scrollbar-color: rgba(82,255,135,.45) rgba(2,9,4,.70);
}

.pdf-modal-body::-webkit-scrollbar {
  width: 10px;
}

.pdf-modal-body::-webkit-scrollbar-track {
  background: rgba(2,9,4,.70);
}

.pdf-modal-body::-webkit-scrollbar-thumb {
  background: rgba(82,255,135,.45);
  border: 2px solid rgba(2,9,4,.70);
}

.pdf-viewer-status {
  min-height: 52px;
  display: grid;
  place-items: center;
  color: var(--green-soft);
  font: 700 11px/1.4 Consolas, "Cascadia Mono", monospace;
  letter-spacing: .08em;
}

.pdf-viewer-status.error {
  color: #ff7272;
}

.pdf-viewer-status[hidden] {
  display: none;
}

.pdf-viewer-pages {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 18px;
}

.pdf-page-wrap {
  position: relative;
  max-width: 100%;
  background: #fff;
  box-shadow: 0 10px 30px rgba(0,0,0,.38), 0 0 0 1px rgba(82,255,135,.08);
}

.pdf-page-wrap canvas {
  display: block;
  max-width: 100%;
  height: auto;
}

.pdf-page-number {
  position: absolute;
  right: 8px;
  bottom: 8px;
  padding: 3px 6px;
  background: rgba(0,0,0,.62);
  color: #c7ffd3;
  font: 700 9px/1 Consolas, monospace;
  letter-spacing: .05em;
}

.dashboard {
  border-top: 1px solid var(--line);
  padding-top: 14px;
  flex: 1 1 auto;
  min-height: 0;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.section-title {
  display: flex;
  justify-content: space-between;
  align-items: end;
  gap: 16px;
  margin-bottom: 10px;
}

.section-title h3 {
  margin-top: 5px;
  font-size: 21px;
}

.counter {
  color: var(--muted);
  font-size: 12px;
}

.counter span {
  color: var(--green);
  font-size: 22px;
  margin-right: 5px;
}

.robot-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(360px, 1fr));
  gap: 12px;
  flex: 1 1 auto;
  min-height: 0;
  overflow-y: auto;
  overflow-x: hidden;
  align-content: start;
  padding-right: 4px;
  scrollbar-width: thin;
  scrollbar-color: rgba(82,255,135,.42) rgba(2,9,4,.60);
}

.robot-grid::-webkit-scrollbar {
  width: 8px;
}

.robot-grid::-webkit-scrollbar-track {
  background: rgba(2,9,4,.60);
}

.robot-grid::-webkit-scrollbar-thumb {
  background: rgba(82,255,135,.42);
  border: 2px solid rgba(2,9,4,.60);
}

.robot-grid::-webkit-scrollbar-thumb:hover {
  background: rgba(82,255,135,.62);
}

.robot-card {
  position: relative;
  overflow: hidden;
  min-height: 180px;
  padding: 14px;
  border: 1px solid var(--line);
  background: linear-gradient(145deg, rgba(5,18,9,.94), rgba(2,8,4,.88));
  transition: transform .18s ease, border-color .18s ease, box-shadow .18s ease;
}

.robot-card::before {
  content: "";
