}

.robot-card:hover {
  transform: translateY(-2px);
  border-color: rgba(82,255,135,.55);
  box-shadow: 0 18px 46px rgba(0,0,0,.3), 0 0 22px rgba(82,255,135,.055);
}

.robot-top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 14px;
}

.robot-identity {
