.robot-icon {
  width: 54px;
  height: 54px;
  min-width: 54px;
  display: grid;
  place-items: center;
  color: #001905;
  background: var(--green);
  border: 1px solid rgba(82,255,135,.72);
  box-shadow: 0 0 20px rgba(82,255,135,.20);
  font: 900 18px Consolas, "Cascadia Mono", monospace;
  letter-spacing: -.08em;
  line-height: 1;
}

.robot-code {
  color: var(--green);
  font-size: 12px;
  letter-spacing: .08em;
}

.robot-badge {
  border: 1px solid var(--line);
  color: var(--green-soft);
  padding: 5px 8px;
  font-size: 9px;
  letter-spacing: .1em;
}

.robot-card h4 {
  margin-top: 5px;
  color: #e7ffed;
  font-size: 20px;
}

.robot-card p {
  margin-top: 9px;
  color: #84a98e;
  line-height: 1.55;
  font-family: "Segoe UI", Arial, sans-serif;
  font-size: 13px;
  min-height: 42px;
}

.robot-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-top: 14px;
}

.availability {
