}

.empty-icon {
  color: var(--green);
  font-size: 30px;
  margin-bottom: 10px;
}

.empty-state h4 {
  color: var(--green-soft);
  font-size: 17px;
}

.empty-state p {
  max-width: 650px;
  margin: 9px auto 0;
  color: var(--muted);
  font-family: "Segoe UI", Arial, sans-serif;
  line-height: 1.55;
}

footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 18px;
  margin-top: 10px;
  padding: 5px 10px 4px;
  border: 1px solid rgba(82,255,135,.40);
  background: rgba(82,255,135,.50);
  color: #020503;
  box-shadow:
    0 0 6px rgba(82,255,135,.03),
    inset 0 1px 0 rgba(255,255,255,.08);
  font-family: "MS Sans Serif", "Microsoft Sans Serif", Tahoma, sans-serif;
  font-size: 10px;
  font-weight: 400;
  line-height: 1.15;
  letter-spacing: 0;
  text-shadow: none;
  text-rendering: optimizeSpeed;
  -webkit-font-smoothing: none;
}

footer,
footer * {
  color: #020503 !important;
  font-family: "MS Sans Serif", "Microsoft Sans Serif", Tahoma, sans-serif !important;
  letter-spacing: 0 !important;
  text-shadow: none !important;
}

.toast {
  position: fixed;
  z-index: 20;
  right: 24px;
  bottom: 24px;
  max-width: 420px;
  padding: 14px 16px;
  border: 1px solid var(--line);
  background: #041008;
  color: var(--green-soft);
  box-shadow: 0 14px 45px rgba(0,0,0,.4);
  font: 12px Consolas, monospace;
  transform: translateY(25px);
  opacity: 0;
  pointer-events: none;
  transition: .2s ease;
}

.toast.show { transform: translateY(0); opacity: 1; }
.toast.error { color: #ff9caa; border-color: rgba(255,92,112,.4); }

@media (max-width: 900px) {
  .side-handle {
    width: 28px;
    height: 108px;
    font-size: 8px;
  }

  .side-panel {
    top: 8px;
    bottom: 8px;
    width: min(340px, calc(100vw - 44px));
  }

  html, body { overflow-y: auto; }
  body { height: auto; min-height: 100vh; }
  .shell {
    width: min(100% - 24px, 1480px);
    height: auto;
    min-height: 100vh;
    overflow: visible;
  }
  .hero { grid-template-columns: 1fr; padding-top: 24px; }
  .process-library { grid-template-columns: 1fr; }
  .topbar, .section-title, footer { align-items: flex-start; flex-direction: column; }
  .node-state { align-self: stretch; }

  .process-library-card {
    grid-template-columns: auto 1fr;
  }

  .process-library-action {
    grid-column: 1 / -1;
    justify-self: end;
  }
}

@media (prefers-reduced-motion: reduce) {
  .scanline::after, .pulse { animation: none; }
}
